<!doctype html>
<html lang="zh-CN"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>第三方订阅管理</title>
<style>
:root{font-family:system-ui,"Microsoft YaHei",sans-serif;color:#182c35;background:#f3f6f7;font-size:15px}*{box-sizing:border-box}body{margin:0}main{max-width:1120px;margin:40px auto;padding:0 24px}header{display:flex;justify-content:space-between;align-items:center;gap:20px}h1{font-size:26px;margin:12px 0}h2{font-size:18px;margin:0 0 20px}p{line-height:1.7;color:#52646d}a{color:#126876}button{font:inherit;border:1px solid #bccbd0;border-radius:5px;background:white;padding:9px 14px;cursor:pointer}button.primary{background:#126876;color:white;border-color:#126876}button:disabled{opacity:.5;cursor:wait}input{font:inherit;padding:10px;border:1px solid #b9c7cd;border-radius:4px;width:100%;background:white}input[type=checkbox]{width:auto}label{display:block;margin:14px 0 6px}section{background:white;border:1px solid #dce4e7;border-radius:8px;padding:24px;margin:22px 0}.toolbar{display:flex;gap:8px;flex-wrap:wrap}.table-wrap{overflow-x:auto}table{width:100%;border-collapse:collapse;min-width:760px}th,td{text-align:left;padding:14px 10px;border-bottom:1px solid #e2e8eb;vertical-align:top}th{color:#52646d;font-size:13px}td small{display:block;color:#52646d;margin-top:6px;max-width:300px;overflow-wrap:anywhere}#message{white-space:pre-wrap;color:#9b3828;line-height:1.6}#plans{display:grid;grid-template-columns:repeat(auto-fit,minmax(180px,1fr));gap:8px;padding:12px;background:#f3f6f7}#plans label{margin:0}.hint{font-size:13px;color:#52646d}button:focus-visible,input:focus-visible,a:focus-visible{outline:3px solid #61afc2;outline-offset:2px}[hidden]{display:none!important}@media(max-width:600px){main{margin:20px auto;padding:0 14px}header{align-items:flex-start;flex-direction:column}section{padding:16px}}
</style></head><body><main>
<header><div><a href="/{{ $adminPath }}">← 返回主后台</a><h1>第三方订阅</h1><p>按套餐分发外部节点 · 每 30 分钟同步 · 失败缓存最多保留 24 小时</p></div><button id="logout" hidden>退出此页面</button></header>
<p id="message" role="status" aria-live="polite"></p>
<section id="login"><h2>管理员登录</h2><p>使用本站管理员账号。登录状态仅保存在当前页面，关闭或刷新页面后需重新登录。</p><form id="loginForm"><label for="email">邮箱</label><input id="email" type="email" autocomplete="username" required><label for="password">密码</label><input id="password" type="password" autocomplete="current-password" required><p><button class="primary">登录</button></p></form></section>
<div id="workspace" hidden><div class="toolbar"><button class="primary" id="add">新增来源</button><button id="reload">刷新列表</button></div>
<section id="editor" hidden><h2 id="editorTitle">新增来源</h2><form id="editForm"><label for="name">来源名称</label><input id="name" maxlength="100" required><label for="url">订阅链接</label><input id="url" type="url" maxlength="4096" autocomplete="off"><p class="hint">编辑时留空保留原链接。更换链接会清除旧节点缓存，需重新同步。链接不会回显。</p><label><input type="checkbox" id="enabled" checked> 启用此来源</label><label>关联套餐（可多选）</label><div id="plans"></div><p class="hint">未选择套餐时不会向任何用户下发。流量用尽、到期或封禁的用户不会获取第三方节点。</p><div class="toolbar"><button class="primary">保存</button><button type="button" id="cancel">取消</button></div></form></section>
<section class="table-wrap"><table><thead><tr><th>来源 / 状态</th><th>关联套餐</th><th>节点</th><th>最近成功同步</th><th>操作</th></tr></thead><tbody id="rows"></tbody></table><p id="empty" hidden>还没有第三方订阅。新增来源并关联套餐后，点击“同步”获取节点。</p></section>
<p class="hint">第三方节点不计入本站流量。停止下发不会撤销用户已经下载的第三方凭据；同步成功也不代表所有节点在线。</p></div>
</main><script>
const adminPath = @json($adminPath);
const $ = id => document.getElementById(id);
let token = '', sources = [], plans = [], editing = null;
const message = text => $('message').textContent = text;
async function request(path, data, auth = true) {
 const response = await fetch('/api/v1/' + path, {method:data ? 'POST':'GET',credentials:'omit',headers:{'Accept':'application/json',...(data ? {'Content-Type':'application/json'}:{}),...(auth ? {'authorization':token}:{})},...(data ? {body:JSON.stringify(data)}:{})});
 let body; try { body = await response.json(); } catch { throw new Error('服务器未返回有效响应，请检查安装与服务日志。'); }
 if (!response.ok) throw new Error(body.message || '请求失败，请检查权限与服务状态。'); return body;
}
async function action(button, fn){button.disabled=true;message('');try{await fn();}catch(e){message(e.message);}finally{button.disabled=false;}}
function cell(row,text){const td=document.createElement('td');td.textContent=text;row.appendChild(td);return td;}
function button(parent,label,fn){const b=document.createElement('button');b.textContent=label;b.onclick=()=>action(b,fn);parent.appendChild(b);}
function edit(source){editing=source;$('editor').hidden=false;$('editorTitle').textContent=source?'编辑来源':'新增来源';$('name').value=source?.name||'';$('url').value='';$('url').required=!source;$('enabled').checked=source?!!Number(source.enabled):true;$('plans').replaceChildren();for(const plan of plans){const label=document.createElement('label'),input=document.createElement('input');input.type='checkbox';input.value=plan.id;input.checked=(source?.plan_ids||[]).map(Number).includes(Number(plan.id));label.append(input,document.createTextNode(' '+plan.name));$('plans').append(label);}$('name').focus();}
async function refresh(){const data=await request(adminPath+'/external-subscription/fetch');sources=data.data;plans=data.plans;$('rows').replaceChildren();$('empty').hidden=sources.length>0;for(const s of sources){const tr=document.createElement('tr');const first=cell(tr,s.name+' · '+(Number(s.enabled)?'启用':'停用'));const status=document.createElement('small');status.textContent=s.status||'等待同步';first.append(status);cell(tr,plans.filter(p=>s.plan_ids.map(Number).includes(Number(p.id))).map(p=>p.name).join('、')||'未绑定');cell(tr,String(s.node_count));cell(tr,s.synced_at?new Date(s.synced_at*1000).toLocaleString():'尚未成功');const ops=cell(tr,'');button(ops,'编辑',async()=>edit(s));button(ops,'同步',async()=>{const result=await request(adminPath+'/external-subscription/sync',{id:s.id});await refresh();message(result.data?'同步完成':'未更新，请查看来源状态（停用或同步中也不会更新）。');});button(ops,'删除',async()=>{if(!confirm('删除来源“'+s.name+'”及其套餐绑定？'))return;await request(adminPath+'/external-subscription/drop',{id:s.id});await refresh();});$('rows').append(tr);}}
$('loginForm').onsubmit=e=>{e.preventDefault();action(e.submitter,async()=>{const result=await request('passport/auth/login',{email:$('email').value,password:$('password').value},false);$('password').value='';if(!result.data?.is_admin)throw new Error('需要管理员账号');token=result.data.auth_data;await refresh();$('login').hidden=true;$('workspace').hidden=false;$('logout').hidden=false;});};
$('editForm').onsubmit=e=>{e.preventDefault();action(e.submitter,async()=>{const data={name:$('name').value,url:$('url').value,enabled:$('enabled').checked,plan_ids:[...$('plans').querySelectorAll('input:checked')].map(i=>Number(i.value))};if(editing){data.id=editing.id;data.revision=editing.revision;}await request(adminPath+'/external-subscription/save',data);$('editor').hidden=true;$('url').value='';await refresh();message('已保存。新增或更换链接后，请点击同步。');});};
$('add').onclick=()=>edit(null);$('cancel').onclick=()=>{$('editor').hidden=true;$('url').value='';};$('reload').onclick=()=>action($('reload'),refresh);$('logout').onclick=()=>location.reload();
</script></body></html>
